"""Find the Index of the First Occurrence in a String — KMP.

Build the prefix function (longest proper prefix that is also a suffix) for the
needle, then scan the haystack without ever moving the read pointer backwards.

Time: O(n + m)   Space: O(m)
"""


class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        if not needle:
            return 0
        lps = [0] * len(needle)
        length = 0
        for i in range(1, len(needle)):
            while length and needle[i] != needle[length]:
                length = lps[length - 1]
            if needle[i] == needle[length]:
                length += 1
                lps[i] = length

        matched = 0
        for i, ch in enumerate(haystack):
            while matched and ch != needle[matched]:
                matched = lps[matched - 1]
            if ch == needle[matched]:
                matched += 1
            if matched == len(needle):
                return i - len(needle) + 1
        return -1
